const renderer=new T.WebGLRenderer({antialias:true});configureSurfaceQuality(renderer.capabilities.getMaxAnisotropy());renderer.setPixelRatio(Math.min(devicePixelRatio,2.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setClearColor('#c3c9cd');renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;host.append(renderer.domElement);$('#loading').remove();
