let machine=null,factory=null,active=-1,time=0,playing=true,speed=1,branch='mould',mode='factory',yaw=.04,pitch=.85,radius=87,last=performance.now(),repeat=false,trace=false,explanations=true;
const target=new T.Vector3(0,1,0),desiredTarget=target.clone();let desiredRadius=radius;
const traceBadge=document.createElement('div');traceBadge.className='traceBadge';traceBadge.textContent='BRICK 001';traceBadge.hidden=true;host.append(traceBadge);
