const leaderLayer=document.createElementNS('http://www.w3.org/2000/svg','svg');leaderLayer.classList.add('labelLeaders');host.append(leaderLayer);const leaders=stages.map(()=>{const line=document.createElementNS('http://www.w3.org/2000/svg','line');leaderLayer.append(line);return line});
function replaceFactory(){if(factory){scene.remove(factory.root);factory.dispose()}factory=buildFactory(branch);factory.setTrace(trace);factory.root.visible=mode==='factory';scene.add(factory.root)}replaceFactory();
