function setTrace(value){trace=value;if(trace&&mode!=='factory')changeMode('factory');factory.setTrace(trace);$('#trace').setAttribute('aria-pressed',String(trace));$('#trace').textContent=trace?'Tracing brick 001 ●':'Trace mode';if(trace){pitch=.55;const state=sample(stages,time);factory.update(time,state.index,state.progress);applyTrace()}}
